public abstract class MeioDeTransporte implements Transportavel { protected final String nome; protected final int capacidade; protected final double velocidade; protected final double custo; protected int passageiros; public MeioDeTransporte(String n,int c,double v,double k){nome=n;capacidade=c;velocidade=v;custo=k;} public void embarcar(int p){if(p<0||p>capacidade)throw new IllegalArgumentException("Capacidade excedida");passageiros=p;System.out.println(nome+" embarcou "+p+" passageiros.");} public void chegar(){System.out.println(nome+" chegou ao destino.");} public int getCapacidade(){return capacidade;} public double getVelocidadeMedia(){return velocidade;} public double getCustoPorKm(){return custo;} }
